package com.rpb.reservation.workforce.leave.account;
import static com.rpb.reservation.workforce.leave.account.LeaveAccountDtos.*;
import com.rpb.reservation.workforce.domain.WorkforceException;
import java.math.BigDecimal;import java.time.*;import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository public class LeaveAccountRepository {
 private final JdbcTemplate jdbc;public LeaveAccountRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
 public List<Account> accounts(UUID tenant,UUID employee,int year){return jdbc.query("select * from workforce_leave_accounts where tenant_id=? and employee_id=? and account_year=? order by kind,id",(r,n)->new Account(r.getObject("id",UUID.class),r.getObject("employee_id",UUID.class),r.getObject("company_id",UUID.class),r.getInt("account_year"),r.getString("kind"),r.getString("unit"),r.getObject("contract_id",UUID.class),r.getObject("opening_on",LocalDate.class),r.getBigDecimal("baseline_accrual"),r.getLong("version")),tenant,employee,year);}
 public Optional<Account> find(UUID tenant,UUID id){var e=jdbc.query("select employee_id,account_year from workforce_leave_accounts where tenant_id=? and id=?",(r,n)->Map.entry(r.getObject(1,UUID.class),r.getInt(2)),tenant,id);return e.isEmpty()?Optional.empty():accounts(tenant,e.getFirst().getKey(),e.getFirst().getValue()).stream().filter(a->a.id().equals(id)).findFirst();}
 public void create(UUID tenant,UUID actor,Account a){jdbc.update("insert into workforce_leave_accounts(id,tenant_id,company_id,employee_id,account_year,kind,unit,contract_id,opening_on,baseline_accrual,version,created_by) values(?,?,?,?,?,?,?,?,?,?,?,?)",a.id(),tenant,a.companyId(),a.employeeId(),a.year(),a.kind(),a.unit(),a.contractId(),a.openingOn(),a.baselineAccrual(),a.version(),actor);}
 public void touch(UUID tenant,UUID id){if(jdbc.update("update workforce_leave_accounts set version=version+1 where tenant_id=? and id=?",tenant,id)!=1)throw WorkforceException.conflict();}
 public void review(UUID tenant,Account a,UUID contract,LocalDate cutoff,BigDecimal accrualOffset){if(jdbc.update("update workforce_leave_accounts set contract_id=?,opening_on=?,baseline_accrual=?,version=version+1 where tenant_id=? and id=? and version=?",contract,cutoff,accrualOffset,tenant,a.id(),a.version())!=1)throw WorkforceException.conflict();}
 public Optional<LocalDate> leftOn(UUID tenant,UUID employee){return jdbc.query("select leave_date from workforce_employees where tenant_id=? and id=? and leave_date is not null",(r,n)->r.getObject(1,LocalDate.class),tenant,employee).stream().findFirst();}
 public List<Lot> lots(UUID tenant,UUID account){return jdbc.query("""
  select l.*,l.quantity+coalesce((select sum(x.quantity) from workforce_leave_ledger x where x.tenant_id=l.tenant_id and x.lot_id=l.id),0) remaining,
  coalesce((select sum(h.quantity) from workforce_leave_holds h where h.tenant_id=l.tenant_id and h.lot_id=l.id and h.status='reserved'),0) reserved
  from workforce_leave_credit_lots l where l.tenant_id=? and l.account_id=? order by l.expires_on,l.created_at,l.id
  """,(r,n)->new Lot(r.getObject("id",UUID.class),r.getObject("account_id",UUID.class),r.getString("origin"),r.getString("source_key"),r.getObject("expires_on",LocalDate.class),r.getBigDecimal("quantity"),r.getBigDecimal("remaining"),r.getBigDecimal("reserved"),r.getObject("contract_id",UUID.class),r.getLong("account_version"),r.getInt("entitlement_year")),tenant,account);}
 public UUID credit(UUID tenant,Account a,String origin,String source,LocalDate expires,BigDecimal quantity){return credit(tenant,a,origin,source,expires,quantity,a.year());}
 public UUID credit(UUID tenant,Account a,String origin,String source,LocalDate expires,BigDecimal quantity,int entitlementYear){if(quantity.signum()<=0)throw WorkforceException.invalid();UUID id=UUID.randomUUID();jdbc.update("insert into workforce_leave_credit_lots(id,tenant_id,account_id,origin,source_key,expires_on,quantity,contract_id,account_version,entitlement_year) values(?,?,?,?,?,?,?,?,?,?)",id,tenant,a.id(),origin,source,expires,quantity,a.contractId(),a.version(),entitlementYear);touch(tenant,a.id());return id;}
 public BigDecimal credited(UUID tenant,UUID account,String origin){return jdbc.queryForObject("select coalesce(sum(quantity),0) from workforce_leave_credit_lots where tenant_id=? and account_id=? and origin=?",BigDecimal.class,tenant,account,origin);}
 public void entry(UUID tenant,UUID actor,Account a,UUID lot,String source,String operation,BigDecimal quantity,String reason){jdbc.update("insert into workforce_leave_ledger(id,tenant_id,account_id,lot_id,source_key,operation,quantity,reason,actor_id,contract_id,account_version) values(?,?,?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),tenant,a.id(),lot,source,operation,quantity,reason,actor,a.contractId(),a.version());touch(tenant,a.id());}
 public List<Entry> history(UUID tenant,UUID account){return jdbc.query("select * from workforce_leave_ledger where tenant_id=? and account_id=? order by created_at,id",(r,n)->new Entry(r.getObject("id",UUID.class),r.getObject("account_id",UUID.class),r.getObject("lot_id",UUID.class),r.getString("source_key"),r.getString("operation"),r.getBigDecimal("quantity"),r.getString("reason"),r.getObject("actor_id",UUID.class),r.getTimestamp("created_at").toInstant(),r.getObject("contract_id",UUID.class),r.getLong("account_version")),tenant,account);}
 public List<Hold> holds(UUID tenant,UUID source){return jdbc.query("select * from workforce_leave_holds where tenant_id=? and source_id=? order by account_id,lot_id",(r,n)->new Hold(r.getObject("source_id",UUID.class),r.getString("source_kind"),r.getObject("account_id",UUID.class),r.getObject("lot_id",UUID.class),r.getBigDecimal("quantity"),r.getString("status")),tenant,source);}
 public void hold(UUID tenant,UUID source,String kind,UUID account,UUID lot,BigDecimal quantity){jdbc.update("insert into workforce_leave_holds(tenant_id,source_id,source_kind,account_id,lot_id,quantity,status) values(?,?,?,?,?,?,'reserved')",tenant,source,kind,account,lot,quantity);touch(tenant,account);}
 public void holdStatus(UUID tenant,UUID source,String status){jdbc.update("update workforce_leave_holds set status=?,updated_at=now() where tenant_id=? and source_id=?",status,tenant,source);}
 public List<Binding> bindings(UUID tenant,UUID store){return jdbc.query("select * from workforce_leave_type_policies where tenant_id=? and store_id=? order by type_id",(r,n)->new Binding(r.getObject("type_id",UUID.class),r.getString("kind"),r.getLong("version")),tenant,store);}
 public void binding(UUID tenant,UUID store,Binding b){jdbc.update("insert into workforce_leave_type_policies(tenant_id,type_id,store_id,kind,version) values(?,?,?,?,?) on conflict(tenant_id,type_id) do update set kind=excluded.kind,version=excluded.version where workforce_leave_type_policies.store_id=excluded.store_id",tenant,b.typeId(),store,b.kind(),b.version());}
 public boolean reconciledOpeningDay(UUID tenant,Account account,LocalDate date){return !date.isAfter(account.openingOn())&&!(date.equals(account.openingOn())&&date.equals(LocalDate.of(account.year(),1,1))&&lots(tenant,account.id()).stream().anyMatch(l->l.origin().equals("grant")&&l.sourceKey().startsWith("year-start:")));}
 public boolean hasUnpaidAfter(UUID tenant,UUID employee,LocalDate from,LocalDate to){return Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from workforce_leaves l join workforce_schedules s on s.tenant_id=l.tenant_id and s.id=l.schedule_id where l.tenant_id=? and l.employee_id=? and not l.paid and l.status in('approved','cancel_requested') and s.work_date>? and s.work_date<=?)",Boolean.class,tenant,employee,from,to));}
 public boolean hasUnreconciledFutureLeave(UUID tenant,UUID employee,UUID company,LocalDate cutoff,int year){
  boolean scheduled=Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from workforce_leaves l join workforce_schedules s on s.id=l.schedule_id and s.tenant_id=l.tenant_id where l.tenant_id=? and l.employee_id=? and s.company_id=? and l.paid and l.status in('pending','approved','cancel_requested') and (s.work_date>? or l.status in('pending','cancel_requested')) and extract(year from s.work_date)=? and not exists(select 1 from workforce_leave_holds h where h.tenant_id=l.tenant_id and h.source_id=l.id))",Boolean.class,tenant,employee,company,cutoff,year));
  return scheduled||Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from workforce_attendance_exceptions l where l.tenant_id=? and l.employee_id=? and l.company_id=? and l.kind='leave' and l.paid and l.status in('pending','approved','cancel_requested') and (l.work_date>? or l.status in('pending','cancel_requested')) and extract(year from l.work_date)=? and not exists(select 1 from workforce_leave_holds h where h.tenant_id=l.tenant_id and h.source_id=l.id))",Boolean.class,tenant,employee,company,cutoff,year));
 }

 public boolean overlaps(UUID tenant,UUID employee,UUID company,UUID exclude,java.time.Instant from,java.time.Instant to){return Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from workforce_leaves l join workforce_schedules s on s.id=l.schedule_id and s.tenant_id=l.tenant_id where l.tenant_id=? and l.employee_id=? and s.company_id=? and l.id<>? and l.status in('pending','approved','cancel_requested') and l.start_at<? and l.end_at>?)",Boolean.class,tenant,employee,company,exclude,java.sql.Timestamp.from(to),java.sql.Timestamp.from(from)));}
}
